function genOrd(nums) {
    const len = nums.length;
    const last = nums[len - 1];
    let max = last + 1;
    while (max > 1) {
        nums.push(max);
        let r;
        let badRoot = max;
        let checked = false;
        while (badRoot >= 1) {
            for (let x = len; x >= 0; x--) {
                if (nums[x] === badRoot) {
                    r = x; //r = bad root pos
                    break;
                }
            }
            // if (r === 0) {
            //     badRoot--; continue;// badroot2: 1,1,2 => []\[2], check badroot1 needed
            // }
            let r2 = -1;
            let foundBrach = false;
            for (let x = r - 1; x >= 0; x--) {
                if (nums[x] < badRoot) {
                    foundBrach = true;
                    break;
                }
                // if (nums[x] >= badRoot && foundBrach===-1) {
                //     foundBrach = x + 1;
                // }
                if (nums[x] === badRoot) {
                    r2 = x; //r = bad root
                    break;
                }
            }
            if (foundBrach || r2 === -1) {
                badRoot--;
                continue;
            }
            const left = nums.slice(r2, r);
            const right = nums.slice(r);
            if (cmp(left, right) >= 0) {
                badRoot--;
            }
            else {
                max--;
                break;
            }
        }
        nums.pop();
        if (badRoot <= 0 || checked)
            break;
    }
    let res = [1];
    for (let i = 2; i <= max; i++) {
        res.push(i);
    }
    return res;
}
